              "legendFormat": "{{instance}} {{device}} tx"
            }
          ]
        },
        {
          "id": 15,
          "type": "barchart",
          "title": "Running Pods per Namespace",
          "gridPos": { "h": 8, "w": 12, "x": 12, "y": 20 },
          "datasource": { "type": "prometheus", "uid": "$datasource" },
          "targets": [
